export const niches = [
  { slug: "skincare", name: "Skincare", keywords: ["serum", "glow", "SPF"] },
  { slug: "haircare", name: "Haircare", keywords: ["shampoo", "curls"] },
  {
    slug: "supplements",
    name: "Supplements",
    keywords: ["protein", "gummies"],
  },
  { slug: "fitness", name: "Fitness", keywords: ["leggings", "dumbbell"] },
  {
    slug: "pet-supplies",
    name: "Pet Supplies",
    keywords: ["collar", "kibble"],
  },
  { slug: "home-decor", name: "Home Decor", keywords: ["sofa", "candle"] },
  { slug: "kitchen", name: "Kitchen", keywords: ["blender", "knife"] },
  { slug: "apparel", name: "Apparel", keywords: ["hoodie", "denim"] },
  { slug: "jewelry", name: "Jewelry", keywords: ["necklace", "ring"] },
  { slug: "baby-kids", name: "Baby & Kids", keywords: ["stroller", "onesie"] },
  { slug: "outdoor", name: "Outdoor", keywords: ["tent", "backpack"] },
  {
    slug: "tech-accessories",
    name: "Tech Accessories",
    keywords: ["charger", "phone case"],
  },
] as const;

export const adFormats = ["image", "video", "carousel"] as const;
export const adStatuses = ["active", "inactive"] as const;

// Assigned ISO 3166-1 alpha-2 codes; not reserved aliases or user-assigned codes.
const countryCodes = new Set(
  `AD AE AF AG AI AL AM AO AQ AR AS AT AU AW AX AZ
   BA BB BD BE BF BG BH BI BJ BL BM BN BO BQ BR BS BT BV BW BY BZ
   CA CC CD CF CG CH CI CK CL CM CN CO CR CU CV CW CX CY CZ
   DE DJ DK DM DO DZ EC EE EG EH ER ES ET FI FJ FK FM FO FR
   GA GB GD GE GF GG GH GI GL GM GN GP GQ GR GS GT GU GW GY
   HK HM HN HR HT HU ID IE IL IM IN IO IQ IR IS IT JE JM JO JP
   KE KG KH KI KM KN KP KR KW KY KZ LA LB LC LI LK LR LS LT LU LV LY
   MA MC MD ME MF MG MH MK ML MM MN MO MP MQ MR MS MT MU MV MW MX MY MZ
   NA NC NE NF NG NI NL NO NP NR NU NZ OM PA PE PF PG PH PK PL PM PN PR PS PT PW PY
   QA RE RO RS RU RW SA SB SC SD SE SG SH SI SJ SK SL SM SN SO SR SS ST SV SX SY SZ
   TC TD TF TG TH TJ TK TL TM TN TO TR TT TV TW TZ UA UG UM US UY UZ
   VA VC VE VG VI VN VU WF WS YE YT ZA ZM ZW`.split(/\s+/),
);

export function isCountryCode(value: unknown): value is string {
  return typeof value === "string" && countryCodes.has(value);
}

type AdTiming = { startDate: string } & ({ status: "active"; endDate: null } | { status: "inactive"; endDate: string });

export type Brand = { id: number; name: string };

export type Ad = AdTiming & {
  id: string;
  brandId: number;
  headline: string;
  bodyText: string;
  niche: (typeof niches)[number]["slug"];
  format: (typeof adFormats)[number];
  impressionRank: number | null;
  countries: string[];
  discoveredAt: Date;
};

// Inputs are validated calendar dates. Subtract UTC midnights, not elapsed local days.
export function daysActive(ad: AdTiming, now: Date = new Date()): number {
  const endDate = ad.status === "inactive" ? ad.endDate : now.toISOString().slice(0, 10);

  return (Date.parse(endDate) - Date.parse(ad.startDate)) / 86_400_000;
}

import { sql } from "drizzle-orm";
import { check, date, integer, pgTable, text, timestamp, unique, uuid } from "drizzle-orm/pg-core";

import { type Ad, adFormats, adStatuses, niches } from "../ads/index.js";

export const users = pgTable("users", {
  id: uuid("id").defaultRandom().primaryKey(),
  username: text("username").notNull().unique(),
  passwordHash: text("password_hash").notNull(),
});

export const brands = pgTable("brands", {
  id: integer("id").primaryKey(),
  name: text("name").notNull(),
});

export const ads = pgTable(
  "ads",
  {
    id: text("id").primaryKey(),
    brandId: integer("brand_id")
      .notNull()
      .references(() => brands.id),
    headline: text("headline").notNull(),
    bodyText: text("body_text").notNull(),
    niche: text("niche").$type<Ad["niche"]>().notNull(),
    format: text("format", { enum: adFormats }).notNull(),
    status: text("status", { enum: adStatuses }).notNull(),
    startDate: date("start_date").notNull(),
    endDate: date("end_date"),
    impressionRank: integer("impression_rank"),
    countries: text("countries").array().notNull(),
    discoveredAt: timestamp("discovered_at", { withTimezone: true }).notNull(),
  },
  (table) => [
    // DDL requires literal catalog constants, not runtime bind parameters.
    check(
      "ads_niche_check",
      sql`${table.niche} IN (${sql.join(
        niches.map(({ slug }) => sql`${slug}`),
        sql`, `,
      )})`.inlineParams(),
    ),
    check(
      "ads_format_check",
      sql`${table.format} IN (${sql.join(
        adFormats.map((format) => sql`${format}`),
        sql`, `,
      )})`.inlineParams(),
    ),
    check(
      "ads_status_check",
      sql`${table.status} IN (${sql.join(
        adStatuses.map((status) => sql`${status}`),
        sql`, `,
      )})`.inlineParams(),
    ),
    check("ads_impression_rank_check", sql`${table.impressionRank} > 0`),
    check(
      "ads_status_end_date_check",
      sql`(${table.status} = 'active' AND ${table.endDate} IS NULL) OR (${table.status} = 'inactive' AND ${table.endDate} IS NOT NULL)`,
    ),
    check("ads_date_order_check", sql`${table.endDate} >= ${table.startDate}`),
    // PostgreSQL's default NULL-distinct uniqueness permits unknown ranks.
    unique("ads_brand_rank_unique").on(table.brandId, table.impressionRank),
  ],
);

export const apiKeys = pgTable("api_keys", {
  id: uuid("id").defaultRandom().primaryKey(),
  userId: uuid("user_id")
    .notNull()
    .references(() => users.id),
  keyHash: text("key_hash").notNull().unique(),
});

import express, { type Express } from "express";

import { createAdsRouter } from "./ads/router.js";
import { createAuthRouter } from "./auth/index.js";
import type { createDatabase } from "./db/client.js";
import { createHealthRouter } from "./health/router.js";
import { handleErrors } from "./shared/middleware/handle-errors.js";

type AppDependencies = {
  db: ReturnType<typeof createDatabase>["db"];
  jwtSecret: string;
};

export function createApp({ db, jwtSecret }: AppDependencies): Express {
  const app = express();

  app.use("/api/health", createHealthRouter({ db }));

  app.use("/api/auth", createAuthRouter({ db, jwtSecret }));

  app.use("/api/v0", createAdsRouter({ db }));

  app.use(handleErrors);

  return app;
}

import { and, count, desc, eq, or, sql } from "drizzle-orm";

import type { createDatabase } from "../db/client.js";
import { ads, brands } from "../db/schema.js";
import { daysActive, niches } from "./model.js";
import type { AdParameters } from "./parameters.js";

const nicheNames = Object.fromEntries(niches.map(({ slug, name }) => [slug, name]));

export async function queryAds(db: ReturnType<typeof createDatabase>["db"], parameters: AdParameters) {
  const pattern = `%${parameters.q.replace(/[\\%_]/g, "\\$&")}%`;
  const filters = and(
    or(sql`${ads.headline} ILIKE ${pattern} ESCAPE ${"\\"}`, sql`${ads.bodyText} ILIKE ${pattern} ESCAPE ${"\\"}`),
    parameters.niche ? eq(ads.niche, parameters.niche) : undefined,
    parameters.format ? eq(ads.format, parameters.format) : undefined,
    parameters.status ? eq(ads.status, parameters.status) : undefined,
  );

  const [{ total }] = await db.select({ total: count() }).from(ads).where(filters);

  const rows = await db
    .select({
      id: ads.id,
      brand: brands.name,
      headline: ads.headline,
      niche: ads.niche,
      format: ads.format,
      status: ads.status,
      startDate: ads.startDate,
      endDate: ads.endDate,
    })
    .from(ads)
    .innerJoin(brands, eq(ads.brandId, brands.id))
    .where(filters)
    // Legacy ordering deliberately has no tiebreaker or snapshot guarantee.
    .orderBy(desc(ads.startDate))
    .limit(parameters.perPage)
    .offset(parameters.offset);

  const now = new Date();

  return {
    data: rows.map((row) => ({
      id: row.id,
      brand: row.brand,
      headline: row.headline,
      niche: nicheNames[row.niche],
      format: row.format,
      status: row.status,
      start_date: row.startDate,
      days_active: daysActive(
        row.status === "active"
          ? { status: "active", startDate: row.startDate, endDate: null }
          : {
              status: "inactive",
              startDate: row.startDate,
              // PostgreSQL enforces a non-null end date for inactive ads.
              endDate: row.endDate as string,
            },
        now,
      ),
    })),
    page: parameters.page,
    total,
  };
}

import { DrizzleQueryError } from "drizzle-orm";
import type { ErrorRequestHandler } from "express";

// Map request failures to
//  - 400 (invalid body)
//  - 503 (database unavailable)
//  - 500 (any other failure)
// without exposing internal error details
export const handleErrors: ErrorRequestHandler = (error: unknown, _req, res, _next) => {
  if (isInvalidRequestBody(error)) {
    res.status(400).json({
      error: { code: "INVALID_REQUEST", message: "Invalid JSON request." },
    });

    return;
  }

  if (isDatabaseUnavailable(error)) {
    console.error("Database unavailable.");

    res.status(503).json({
      error: {
        code: "SERVICE_UNAVAILABLE",
        message: "Service unavailable.",
      },
    });

    return;
  }

  console.error("Unexpected request failure.");

  res.status(500).json({
    error: { code: "INTERNAL_ERROR", message: "Internal server error." },
  });
};

function isInvalidRequestBody(error: unknown): boolean {
  return (
    error instanceof Error &&
    "type" in error &&
    [
      "entity.parse.failed",
      "entity.too.large",
      "encoding.unsupported",
      "charset.unsupported",
      "request.aborted",
      "request.size.invalid",
    ].includes(String(error.type))
  );
}

function isDatabaseUnavailable(error: unknown): boolean {
  if (!(error instanceof DrizzleQueryError)) return false;

  const { cause } = error;

  // Node may aggregate failed connection attempts to multiple addresses.
  return (
    isDatabaseUnavailableCause(cause) ||
    (cause instanceof AggregateError && cause.errors.some(isDatabaseUnavailableCause))
  );
}

function isDatabaseUnavailableCause(error: unknown): boolean {
  if (!(error instanceof Error)) return false;

  // pg's client-side query and connection deadlines emit exact code-less errors.
  // The query deadline can race PostgreSQL's statement_timeout (57014).
  if (!("code" in error)) {
    return (
      error.message === "Query read timeout" || error.message === "Connection terminated due to connection timeout"
    );
  }

  const { code } = error;

  return (
    typeof code === "string" &&
    (code.startsWith("08") || // PostgreSQL connection exceptions
      code.startsWith("53") || // PostgreSQL insufficient resources
      [
        // PostgreSQL shutdown, recovery, and query cancellation
        "57P01",
        "57P02",
        "57P03",
        "57P04",
        "57P05",
        "57014",
        // Node.js network and DNS failures
        "ECONNREFUSED",
        "ECONNRESET",
        "ETIMEDOUT",
        "EPIPE",
        "EHOSTUNREACH",
        "ENETUNREACH",
        "ENOTFOUND",
        "EAI_AGAIN",
      ].includes(code))
  );
}

import { and, eq, inArray, lte, max } from "drizzle-orm";

import { isCountryCode } from "../ads/index.js";
import type { createDatabase } from "../db/client.js";
import { ads, brands } from "../db/schema.js";
import { createIngestAd } from "./ad.js";

export function validateIngestCountries(countries: unknown): asserts countries is string[] {
  if (!Array.isArray(countries) || !countries.every(isCountryCode)) {
    throw new Error("Invalid ingest countries.");
  }
}

// One caller/process owns scheduling; no concurrent ingest workers are supported.
export async function runIngestTick(
  db: ReturnType<typeof createDatabase>["db"],
  {
    clock = () => new Date(),
    random = Math.random,
  }: {
    clock?: () => Date;
    random?: () => number;
  } = {},
): Promise<void> {
  await db.transaction(async (tx) => {
    const now = clock();
    const today = now.toISOString().slice(0, 10);
    const insertCount = 1 + Math.floor(random() * 5);
    const deactivateCount = 1 + Math.floor(random() * 2);
    const availableBrands = await tx.select({ id: brands.id }).from(brands).orderBy(brands.id);

    if (!availableBrands.length) {
      throw new Error("Ingest requires existing brands.");
    }

    // Materialize only IDs, in stable order so injected randomness controls selection.
    // Future-starting active ads cannot receive a valid end date today.
    const candidates = await tx
      .select({ id: ads.id })
      .from(ads)
      .where(and(eq(ads.status, "active"), lte(ads.startDate, today)))
      .orderBy(ads.id);

    const selected: string[] = [];

    while (selected.length < deactivateCount && candidates.length) {
      const [candidate] = candidates.splice(Math.floor(random() * candidates.length), 1);
      selected.push(candidate.id);
    }

    if (selected.length) {
      await tx.update(ads).set({ status: "inactive", endDate: today }).where(inArray(ads.id, selected));
    }

    const maxima = new Map(
      (
        await tx
          .select({ brandId: ads.brandId, rank: max(ads.impressionRank) })
          .from(ads)
          .groupBy(ads.brandId)
      ).map(({ brandId, rank }) => [brandId, rank ?? 0]),
    );

    for (let index = 0; index < insertCount; index++) {
      const brand = availableBrands[Math.floor(random() * availableBrands.length)];
      const ad = createIngestAd({ brandId: brand.id, now, random });

      validateIngestCountries(ad.countries);

      if (ad.impressionRank !== null) {
        const rank = (maxima.get(brand.id) ?? 0) + 1;

        if (rank > 2_147_483_647) {
          throw new Error("Ingest rank space exhausted.");
        }

        ad.impressionRank = rank;
        maxima.set(brand.id, rank);
      }

      await tx.insert(ads).values(ad);
    }
  });
}

import { type Ad, adFormats, adStatuses, niches } from "./model.js";

export type AdParameters = {
  q: string;
  niche: Ad["niche"] | undefined;
  format: Ad["format"] | undefined;
  status: Ad["status"] | undefined;
  apiKey: string;
  page: number;
  perPage: number;
  offset: number;
};

const recognizedNames = ["q", "niche", "format", "status", "page", "per_page", "api_key"] as const;

function positiveInteger(value: string | null, fallback: number): number | null {
  if (value === null) {
    return fallback;
  }

  if (!/^[0-9]+$/.test(value)) {
    return null;
  }

  const number = Number(value);

  return Number.isSafeInteger(number) && number > 0 ? number : null;
}

// null lets the v0 router map all invalid requests to its generic 400 response.
export function parseAdParameters(query: URLSearchParams): AdParameters | null {
  if (recognizedNames.some((name) => query.getAll(name).length > 1)) {
    return null;
  }

  const apiKey = query.get("api_key");

  if (apiKey === null || apiKey === "") {
    return null;
  }

  const page = positiveInteger(query.get("page"), 1);
  const requestedPerPage = positiveInteger(query.get("per_page"), 20);

  if (page === null || requestedPerPage === null) {
    return null;
  }

  const perPage = Math.min(requestedPerPage, 100);
  const offset = (page - 1) * perPage;

  if (!Number.isSafeInteger(offset)) {
    return null;
  }

  const niche = query.get("niche")?.toLowerCase();

  return {
    q: query.get("q") ?? "",
    niche: niches.find(({ slug, name }) => slug === niche || name.toLowerCase() === niche)?.slug,
    format: adFormats.find((format) => format === query.get("format")),
    status: adStatuses.find((status) => status === query.get("status")),
    apiKey,
    page,
    perPage,
    offset,
  };
}

