import { and, eq, inArray, lte, max } from "drizzle-orm";

import { isCountryCode } from "../ads/index.js";
import type { createDatabase } from "../db/client.js";
import { ads, brands } from "../db/schema.js";
import { createIngestAd } from "./ad.js";

export function validateIngestCountries(countries: unknown): asserts countries is string[] {
  if (!Array.isArray(countries) || !countries.every(isCountryCode)) {
    throw new Error("Invalid ingest countries.");
  }
}

// One caller/process owns scheduling; no concurrent ingest workers are supported.
export async function runIngestTick(
  db: ReturnType<typeof createDatabase>["db"],
  {
    clock = () => new Date(),
    random = Math.random,
  }: {
    clock?: () => Date;
    random?: () => number;
  } = {},
): Promise<void> {
  await db.transaction(async (tx) => {
    const now = clock();
    const today = now.toISOString().slice(0, 10);
    const insertCount = 1 + Math.floor(random() * 5);
    const deactivateCount = 1 + Math.floor(random() * 2);
    const availableBrands = await tx.select({ id: brands.id }).from(brands).orderBy(brands.id);

    if (!availableBrands.length) {
      throw new Error("Ingest requires existing brands.");
    }

    // Materialize only IDs, in stable order so injected randomness controls selection.
    // Future-starting active ads cannot receive a valid end date today.
    const candidates = await tx
      .select({ id: ads.id })
      .from(ads)
      .where(and(eq(ads.status, "active"), lte(ads.startDate, today)))
      .orderBy(ads.id);

    const selected: string[] = [];

    while (selected.length < deactivateCount && candidates.length) {
      const [candidate] = candidates.splice(Math.floor(random() * candidates.length), 1);
      selected.push(candidate.id);
    }

    if (selected.length) {
      await tx.update(ads).set({ status: "inactive", endDate: today }).where(inArray(ads.id, selected));
    }

    const maxima = new Map(
      (
        await tx
          .select({ brandId: ads.brandId, rank: max(ads.impressionRank) })
          .from(ads)
          .groupBy(ads.brandId)
      ).map(({ brandId, rank }) => [brandId, rank ?? 0]),
    );

    for (let index = 0; index < insertCount; index++) {
      const brand = availableBrands[Math.floor(random() * availableBrands.length)];
      const ad = createIngestAd({ brandId: brand.id, now, random });

      validateIngestCountries(ad.countries);

      if (ad.impressionRank !== null) {
        const rank = (maxima.get(brand.id) ?? 0) + 1;

        if (rank > 2_147_483_647) {
          throw new Error("Ingest rank space exhausted.");
        }

        ad.impressionRank = rank;
        maxima.set(brand.id, rank);
      }

      await tx.insert(ads).values(ad);
    }
  });
}

import { randomUUID } from "node:crypto";

import { type Ad, adFormats, niches } from "../ads/index.js";

export function createIngestAd({ brandId, now, random }: { brandId: number; now: Date; random: () => number }): Ad {
  const niche = niches[Math.floor(random() * niches.length)];
  const format = adFormats[Math.floor(random() * adFormats.length)];
  const daysBack = random() < 0.3 ? 1 + Math.floor(random() * 90) : 0;
  const start = new Date(now);

  start.setUTCDate(start.getUTCDate() - daysBack);

  return {
    id: `ingest-ad-${randomUUID()}`,
    brandId,
    headline: `Discover ${niche.keywords[0]}`,
    bodyText: `Explore our latest ${niche.name} collection.`,
    niche: niche.slug,
    format,
    status: "active",
    startDate: start.toISOString().slice(0, 10),
    endDate: null,
    // The transaction replaces this positive marker with the next brand-local rank.
    impressionRank: random() < 0.4 ? null : 1,
    countries: ["US", "GB"],
    discoveredAt: now,
  };
}

import { drizzle } from "drizzle-orm/node-postgres";
import pg from "pg";

import * as schema from "./schema.js";

// The caller owns this pool: create at startup, close during shutdown/teardown.
// Importing this module neither opens connections nor runs migrations.
export function createDatabase(databaseUrl: string) {
  const pool = new pg.Pool({
    connectionString: databaseUrl,
    connectionTimeoutMillis: 2000,
    statement_timeout: 2000,
    query_timeout: 2000,
  });

  // Idle clients can fail outside a query; pg removes them before reconnecting.
  // https://node-postgres.com/apis/pool#error
  pool.on("error", () => {
    console.error("Database idle connection lost.");
  });

  const db = drizzle({ client: pool, schema });

  return { db, close: () => pool.end() };
}

import { readFileSync } from "node:fs";
import { parse } from "dotenv";

type Environment = Record<string, string | undefined>;

type ConfigOptions = {
  env?: Environment;
  envFile?: string | URL | null;
  context?: "host" | "container";
};

// Public local-development placeholder, never a production signing secret.
const developmentJwtSecret = "gethookd-public-development-secret-do-not-use-in-production";

export function loadConfig({
  env = process.env,
  envFile = new URL("../../../.env", import.meta.url),
  context = "host",
}: ConfigOptions = {}) {
  const values: Environment = {};
  if (envFile !== null) {
    try {
      Object.assign(values, parse(readFileSync(envFile)));
    } catch (error) {
      if (!(error instanceof Error && "code" in error && error.code === "ENOENT")) {
        throw new Error("Unable to read root .env");
      }
    }
  }
  for (const [key, value] of Object.entries(env)) {
    if (value !== undefined) values[key] = value;
  }

  function setting(key: string, fallback: string) {
    const value = values[key] ?? fallback;
    if (!value.trim() || /\p{Cc}/u.test(value)) {
      throw new Error(`Invalid ${key}`);
    }
    return value;
  }

  const postgresUser = setting("POSTGRES_USER", "gethookd");
  const postgresPassword = setting("POSTGRES_PASSWORD", "gethookd");
  const postgresDb = setting("POSTGRES_DB", "gethookd");
  const jwtSecret = setting("JWT_SECRET", developmentJwtSecret);
  if (Buffer.byteLength(jwtSecret, "utf8") < 32) {
    throw new Error("Invalid JWT_SECRET");
  }

  function encode(key: string, value: string) {
    try {
      return encodeURIComponent(value);
    } catch {
      throw new Error(`Invalid ${key}`);
    }
  }

  const host = context === "container" ? "db" : "localhost";
  const derivedUrl = `postgresql://${encode("POSTGRES_USER", postgresUser)}:${encode("POSTGRES_PASSWORD", postgresPassword)}@${host}:5432/${encode("POSTGRES_DB", postgresDb)}`;
  const databaseUrl = setting("DATABASE_URL", derivedUrl);
  try {
    const url = new URL(databaseUrl);
    decodeURI(databaseUrl);
    if (
      !["postgres:", "postgresql:"].includes(url.protocol) ||
      !url.hostname ||
      url.pathname.length <= 1 ||
      url.hash ||
      /\s/.test(databaseUrl)
    ) {
      throw new Error();
    }
  } catch {
    throw new Error("Invalid DATABASE_URL");
  }

  return { postgresUser, postgresPassword, postgresDb, databaseUrl, jwtSecret };
}

import { createHash } from "node:crypto";
import { eq } from "drizzle-orm";

import type { createDatabase } from "../db/client.js";
import { apiKeys } from "../db/schema.js";

type Database = ReturnType<typeof createDatabase>["db"];

export function hashApiKey(key: string): string {
  return createHash("sha256").update(key, "utf8").digest("hex");
}

export async function validateApiKey(db: Database, key: unknown) {
  if (typeof key !== "string" || key.length === 0) {
    return null;
  }

  const [owner] = await db
    .select({ userId: apiKeys.userId })
    .from(apiKeys)
    .where(eq(apiKeys.keyHash, hashApiKey(key)))
    .limit(1);

  return owner ?? null;
}

import { type RequestHandler, Router } from "express";

import { validateApiKey } from "../api-keys/index.js";
import type { createDatabase } from "../db/client.js";
import { disableCaching } from "../shared/middleware/disable-caching.js";
import { parseAdParameters } from "./parameters.js";
import { queryAds } from "./query.js";

function createGetAdsHandler(db: ReturnType<typeof createDatabase>["db"]): RequestHandler {
  return async function handleGetAds(req, res) {
    try {
      const parameters = parseAdParameters(new URL(req.originalUrl, "http://localhost").searchParams);

      if (!parameters || !(await validateApiKey(db, parameters.apiKey))) {
        res.status(400).json({ error: "Invalid request" });
        return;
      }

      res.json(await queryAds(db, parameters));
    } catch {
      // Keep legacy failures local; raw errors and request URLs can contain keys.
      res.status(400).json({ error: "Invalid request" });
    }
  };
}

export function createAdsRouter({ db }: { db: ReturnType<typeof createDatabase>["db"] }) {
  const router = Router();
  const handleGetAds = createGetAdsHandler(db);

  router.use(disableCaching);
  router.get("/ads", handleGetAds);

  return router;
}

import { execFile, spawn } from "node:child_process";
import { randomUUID } from "node:crypto";
import { fileURLToPath } from "node:url";
import type { TestProject } from "vitest/node";

export default async function setup(project: TestProject) {
  const runId = randomUUID().replaceAll("-", "");
  const projectName = `gethookd-test-${runId}`;
  const composeFile = fileURLToPath(new URL("../../../compose.test.yaml", import.meta.url));
  const env = { ...process.env, GETHOOKD_TEST_RUN_ID: runId };
  const compose = ["compose", "--file", composeFile, "--project-name", projectName];

  function docker(stage: string, args: string[], timeout = 15000): Promise<string> {
    return new Promise((resolve, reject) => {
      const child = spawn("docker", args, {
        env,
        detached: process.platform !== "win32",
        windowsHide: true,
        stdio: ["ignore", "pipe", "pipe"],
      });
      let output = "";
      let terminated = false;
      const failure = () =>
        new Error(
          `PostgreSQL tests: ${stage} failed for ${projectName}. Docker Engine and Compose are required; check daemon availability and test-owned resources.`,
        );
      function terminateTree() {
        terminated = true;
        if (!child.pid) return;
        if (process.platform === "win32") {
          execFile("taskkill", ["/PID", String(child.pid), "/T", "/F"], { timeout: 5000 }, () => child.kill("SIGKILL"));
        } else {
          try {
            process.kill(-child.pid, "SIGKILL");
          } catch {
            child.kill("SIGKILL");
          }
        }
      }
      // Kill the CLI and Compose plugin together, then await pipe/process closure
      // before inspecting ownership or deleting any resources.
      const deadline = setTimeout(terminateTree, timeout);
      child.stdout.on("data", (chunk) => {
        output += chunk.toString();
        if (output.length > 1024 * 1024) terminateTree();
      });
      child.stderr.resume(); // Drain diagnostics without printing possible secrets.
      child.once("error", () => {
        clearTimeout(deadline);
        reject(failure());
      });
      child.once("close", (code) => {
        clearTimeout(deadline);
        if (code === 0 && !terminated) resolve(output.trim());
        else reject(failure());
      });
    });
  }

  async function cleanup() {
    // Read ownership evidence before deleting anything; never prune or target a
    // project supplied by the caller, developer environment, or database URL.
    for (const kind of ["container", "volume", "network"]) {
      const names = await docker("cleanup discovery", [
        kind,
        "ls",
        ...(kind === "container" ? ["--all"] : []),
        "--filter",
        `label=com.docker.compose.project=${projectName}`,
        "--format",
        kind === "volume" ? "{{.Name}}" : "{{.ID}}",
      ]);
      if (!names) continue;
      const resources = JSON.parse(
        await docker("cleanup ownership inspection", [kind, "inspect", ...names.split(/\s+/)]),
      );
      for (const resource of resources) {
        const labels = kind === "container" ? resource.Config.Labels : resource.Labels;
        if (labels?.["io.gethookd.test-run"] !== runId || labels?.["com.docker.compose.project"] !== projectName) {
          throw new Error(`PostgreSQL tests: refusing cleanup without ownership evidence for ${projectName}`);
        }
      }
    }
    await docker("cleanup", [...compose, "down", "--volumes", "--timeout", "5"], 30000);
    console.info(`[postgres] cleaned ${projectName}`);
  }

  await docker("prerequisite check", ["info", "--format", "{{.ServerVersion}}"]);
  console.info(`[postgres] provisioning ${projectName}`);
  try {
    await docker(
      "provisioning/readiness (30s health limit)",
      [...compose, "up", "--detach", "--wait", "--wait-timeout", "30"],
      120000,
    );
    const address = await docker("port discovery", [...compose, "port", "db", "5432"]);
    const match = /^127\.0\.0\.1:(\d+)$/.exec(address);
    if (!match || Number(match[1]) < 1 || Number(match[1]) > 65535) {
      throw new Error("PostgreSQL tests: invalid loopback port mapping");
    }
    project.provide("postgresProject", projectName);
    project.provide(
      "postgresUrl",
      `postgresql://gethookd_test:public-disposable-test-password@127.0.0.1:${match[1]}/gethookd_test`,
    );
  } catch (error) {
    try {
      await cleanup();
    } catch (cleanupError) {
      throw new AggregateError([error, cleanupError], "PostgreSQL test setup and cleanup failed");
    }
    throw error;
  }
  return cleanup;
}

